import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

export async function runMotionAddImageSmoke(page){
 const previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));
 const dir=await fs.mkdtemp(path.join(os.tmpdir(),'nagweb-new-image-')),a=path.join(dir,'Propia.svg'),b=path.join(dir,'Otra.svg'),bad=path.join(dir,'Invalida.txt');
 await fs.writeFile(a,'<svg xmlns="http://www.w3.org/2000/svg" width="300" height="180"><rect width="300" height="180" fill="tomato"/></svg>');await fs.writeFile(b,'<svg xmlns="http://www.w3.org/2000/svg" width="160" height="320"><rect width="160" height="320" fill="royalblue"/></svg>');await fs.writeFile(bad,'No es una imagen');
 try{
  await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[mkEl('label',{name:'Exterior',text:'Fuera del grupo'})]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});
  const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),assets:project.assets.images.length,outside:sec().elements[0]}));
  async function frame(){await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('[data-motion-canvas]'));}
  async function layers(){return page.$$eval('[data-motion-layer]',ns=>ns.map(n=>({id:n.dataset.motionLayer,name:n.querySelector('strong').textContent})));}
  async function choose(id){await page.click('[data-motion-layer="'+id+'"]');}
  async function remove(id){await choose(id);await page.click('[data-motion-element-remove]');await page.waitForFunction(id=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.querySelector('[data-motion-canvas]')&&!d.querySelector('[data-id="'+id+'"]');},{},id);}
  async function added(old,width){await page.waitForFunction(width=>{const lab=document.querySelector('.nw-motion-dialog'),n=lab.querySelector('iframe')?.contentDocument?.querySelector('.nw-motion-selected img');return !lab.querySelector('[data-motion-add-image]').disabled&&n?.complete&&n.naturalWidth===width;},{timeout:10000},width);const row=(await layers()).find(n=>!old.some(e=>e.id===n.id));assert.ok(row);return row;}
  async function upload(file,chooser=false){if(chooser){const choosing=page.waitForFileChooser();await page.click('[data-motion-add-image]');await (await choosing).accept([file]);}else await (await page.$('[data-motion-add-image-upload]')).uploadFile(file);}
  async function change(selector,value){await page.$eval(selector,(n,v)=>{n.value=v;n.dispatchEvent(new Event('change',{bubbles:true}));},value);}
  async function pose(id,selector='.nw-motion-dialog iframe',gid){return page.evaluate(({id,selector,gid})=>{const f=document.querySelector(selector),d=f.contentDocument;f.contentWindow.__NAG_SCROLL_DIRECTOR[gid||d.querySelector('.sc').dataset.id].set(.5);const n=d.querySelector('[data-id="'+id+'"]'),r=n.getBoundingClientRect(),img=n.querySelector('img');return {x:n.style.getPropertyValue('--nw-sd-x'),z:n.style.getPropertyValue('--nw-sd-z'),opacity:d.defaultView.getComputedStyle(n).opacity,base:[n.style.left,n.style.top,n.style.width],ratio:r.height/r.width,natural:[img.naturalWidth,img.naturalHeight],src:img.getAttribute('src')};},{id,selector,gid});}
  await page.click('.tb-left [data-motion-open]');await frame();await page.click('[data-motion-library-tab="elements"]');const original=await layers();for(const row of original.slice(0,3))await remove(row.id);const textOnly=await layers();
  const cancel=page.waitForFileChooser();await page.click('[data-motion-add-image]');await (await cancel).cancel();assert.deepEqual(await layers(),textOnly,'Cancel does not create an empty element');
  await upload(bad);await page.waitForFunction(()=>!document.querySelector('[data-motion-add-image]').disabled&&document.querySelector('[data-motion-add-image-status]').textContent.includes('No se pudo'));assert.deepEqual(await layers(),textOnly,'Invalid file does not create an element');
  await upload(a,true);const first=await added(textOnly,300);assert.equal(first.name,'Imagen nueva');const neutral=await pose(first.id);assert.deepEqual(neutral.natural,[300,180]);assert.ok(Math.abs(neutral.ratio-.6)<.001,'Original image aspect ratio is visible');assert.equal(neutral.x,'0.00px');assert.equal(neutral.z,'0.00px');assert.equal(neutral.opacity,'1');assert.deepEqual(await page.$$eval('[data-motion-key] option',ns=>ns.map(n=>parseFloat(n.textContent))),[0,100]);await page.select('[data-motion-key]',await page.$eval('[data-motion-key] option',n=>n.value));await change('[data-motion-key-property="z"]','-200');await page.$eval('[data-motion-key-more]',n=>n.open=true);await change('[data-motion-key-property="x"]','80');const prepared=await pose(first.id);assert.equal(prepared.x,'40.00px');assert.equal(prepared.z,'-100.00px');assert.deepEqual(prepared.base,neutral.base);
  // A delayed addition belongs to its own cached draft even if another template is active.
  const withFirst=await layers();await page.evaluate(()=>{window.addImageNativeReader=FileReader;window.FileReader=class extends FileReader{readAsDataURL(file){setTimeout(()=>super.readAsDataURL(file),500);}};});await upload(b);assert.equal(await page.$$eval('[data-motion-add-image],[data-motion-add-text],[data-motion-duplicate],[data-motion-element-remove],[data-motion-insert-group]',ns=>ns.every(n=>n.disabled)),true);assert.equal(await page.evaluate(()=>NAGWEB_MOTION_LAB.insertGroup()),false);await page.click('[data-motion-library-tab="library"]');await page.click('[data-motion-template="soft-orbit"]');await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('.hd')?.textContent==='Diseño en movimiento.');await new Promise(r=>setTimeout(r,700));assert.equal(await page.$$eval('[data-motion-content="0"] option',ns=>ns.some(n=>n.textContent==='Otra.svg')),false);await page.evaluate(()=>{window.FileReader=window.addImageNativeReader;delete window.addImageNativeReader;});await page.click('[data-motion-template="iso-focus"]');const second=await added(withFirst,160);assert.equal(second.name,'Imagen nueva 2');assert.ok(Math.abs((await pose(second.id)).ratio-2)<.001);await page.click('[data-motion-library-tab="elements"]');await remove(second.id);await choose(first.id);await page.click('[data-motion-duplicate]');const copied=(await layers()).find(n=>!withFirst.some(e=>e.id===n.id));await page.waitForFunction(id=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('[data-id="'+id+'"].nw-motion-selected img')?.naturalWidth===300,{},copied.id);await choose(first.id);assert.deepEqual(await pose(first.id),prepared);
  assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);assert.equal(await page.evaluate(()=>history.length),0);await page.click('[data-motion-insert-group]');
  const inserted=await page.evaluate(()=>{const g=sec().elements.find(e=>e.nwMotionInstance);return {project:JSON.stringify(project),gid:g.id,members:sec().elements.filter(e=>e.parent===g.id),assets:project.assets.images,outside:sec().elements[0],scroll:sec().sdEnabled};});assert.equal(inserted.members.length,5);assert.equal(inserted.assets.length,before.assets+1,'Only the one used resource is committed');assert.equal(inserted.assets.some(e=>e.name==='Otra.svg'),false);assert.equal(inserted.scroll,false);assert.deepEqual(inserted.outside,before.outside);const image=inserted.members.find(e=>e.id===first.id),copy=inserted.members.find(e=>e.id===copied.id);assert.equal(image.ratio,.6);assert.equal(image.mobile.w,48);assert.equal(image.w,36);assert.equal(copy.assetId,image.assetId);assert.notEqual(copy.sdKeyframes[0].id,image.sdKeyframes[0].id);
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.gid);await frame();await page.click('[data-motion-library-tab="elements"]');const old=await layers();await upload(b);const third=await added(old,160);await page.click('[data-motion-save]');const saved=await page.evaluate(gid=>({project:JSON.stringify(project),members:sec().elements.filter(e=>e.parent===gid),groups:sec().elements.filter(e=>e.nwMotionInstance).length,assets:project.assets.images.length,outside:sec().elements[0]}),inserted.gid);assert.equal(saved.groups,1);assert.equal(saved.members.length,6);assert.equal(saved.assets,inserted.assets.length+1);assert.equal(saved.members.find(e=>e.id===third.id).ratio,2);assert.deepEqual(saved.members.find(e=>e.id===first.id),image);assert.deepEqual(saved.outside,before.outside);
  // Completing a load after closing cannot insert it into a newly opened session.
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.gid);await frame();await page.click('[data-motion-library-tab="elements"]');await page.evaluate(()=>{window.addImageNativeReader=FileReader;window.FileReader=class extends FileReader{readAsDataURL(file){setTimeout(()=>super.readAsDataURL(file),500);}};});await upload(a);assert.equal(await page.$eval('[data-motion-save]',n=>n.disabled),true);await page.click('[data-motion-close]');await page.evaluate(()=>{window.FileReader=window.addImageNativeReader;delete window.addImageNativeReader;});await page.click('.tb-left [data-motion-open]');await frame();await new Promise(r=>setTimeout(r,700));assert.equal((await layers()).length,6);assert.equal(await page.$$eval('[data-motion-content="0"] option',ns=>ns.filter(n=>n.textContent==='Propia.svg').length),1,'Late upload adds no resource to the new session');await page.click('[data-motion-close]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);
  await page.evaluate(()=>{const f=document.createElement('iframe');f.id='add-image-export';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(({gid,id})=>{const f=document.querySelector('#add-image-export');return f?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid]&&f.contentDocument.querySelector('[data-id="'+id+'"] img')?.naturalWidth===300;},{},{gid:inserted.gid,id:first.id});const exported=await pose(first.id,'#add-image-export',inserted.gid);for(const key of ['x','z','opacity','src','natural'])assert.deepEqual(exported[key],prepared[key]);await page.waitForFunction(id=>document.querySelector('#add-image-export')?.contentDocument?.querySelector('[data-id="'+id+'"] img')?.naturalWidth===160,{},third.id);
  console.log('Agregar imagen Motion Lab: selector/cancelar/inválida, sin imágenes previas, proporción real, movimiento propio, carga pendiente/borrador/cache/sesión, recursos usados y copias, Tiempo sin Director, guardar misma instancia, externos, historial y exportación OK');
 }finally{
  await page.evaluate(p=>{if(window.addImageNativeReader){window.FileReader=window.addImageNativeReader;delete window.addImageNativeReader;}document.querySelector('.nw-motion-dialog').close();document.querySelector('#add-image-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);await fs.rm(dir,{recursive:true,force:true});
 }
}
